class BottleLedgerEventType(str, Enum):
    ENTRADA = "ENTRADA"
    REUBICACION = "REUBICACION"
    TRANSFERENCIA = "TRANSFERENCIA"
    SALIDA_SERVICIO = "SALIDA_SERVICIO"
    APERTURA = "APERTURA"
    CONSUMO_PARCIAL = "CONSUMO_PARCIAL"
    CONSUMO_TOTAL = "CONSUMO_TOTAL"
    RETORNO = "RETORNO"
    RETIRO = "RETIRO"
    ROTURA = "ROTURA"
    MERMA = "MERMA"
    AJUSTE = "AJUSTE"
    TRANSFERENCIA_PROPIEDAD = "TRANSFERENCIA_PROPIEDAD"
    BLOQUEO = "BLOQUEO"
    DESBLOQUEO = "DESBLOQUEO"


@dataclass(frozen=True)
class BottleLedgerEvent:
    event_id: str
    bottle_id: str
    assignment_id: str
    event_type: BottleLedgerEventType
    actor_user_id: str
    previous_balance: float
    new_balance: float
    evidence_reference: Optional[str] = None
    source_event_id: Optional[str] = None
    reason: Optional[str] = None


def consumed_delta(previous_balance: float, new_balance: float) -> float:
    previous = float(previous_balance)
    new = float(new_balance)
    if previous < 0 or previous > 1 or new < 0 or new > 1:
        raise ValueError("Los saldos de botella deben estar entre 0 y 1")
    if new > previous:
        raise ValueError("Un consumo no puede incrementar el saldo")
    return round(previous - new, 6)


def validate_bottle_ledger_event(event: BottleLedgerEvent) -> None:
    for field_name, value in (
        ("event_id", event.event_id),
        ("bottle_id", event.bottle_id),
        ("assignment_id", event.assignment_id),
        ("actor_user_id", event.actor_user_id),
    ):
        if not str(value or "").strip():
            raise ValueError(f"BottleLedgerEvent requiere {field_name}")

    previous = float(event.previous_balance)
    new = float(event.new_balance)
    if previous < 0 or previous > 1 or new < 0 or new > 1:
        raise ValueError("Los saldos de botella deben estar entre 0 y 1")

    if event.event_type == BottleLedgerEventType.ENTRADA:
        if new <= 0:
            raise ValueError("ENTRADA debe dejar saldo positivo")
        return

    if event.event_type == BottleLedgerEventType.CONSUMO_PARCIAL:
        delta = consumed_delta(previous, new)
        if delta <= 0 or new <= 0:
            raise ValueError("CONSUMO_PARCIAL requiere reducción positiva y saldo remanente")
        return

    if event.event_type == BottleLedgerEventType.CONSUMO_TOTAL:
        if previous <= 0 or new != 0:
            raise ValueError("CONSUMO_TOTAL debe terminar en saldo 0")
        return

    if event.event_type in {BottleLedgerEventType.REUBICACION, BottleLedgerEventType.APERTURA, BottleLedgerEventType.BLOQUEO, BottleLedgerEventType.DESBLOQUEO, BottleLedgerEventType.TRANSFERENCIA_PROPIEDAD}:
        if new != previous:
            raise ValueError(f"{event.event_type.value} no debe alterar saldo por sí mismo")
        return

    if event.event_type in {BottleLedgerEventType.ROTURA, BottleLedgerEventType.MERMA, BottleLedgerEventType.RETIRO}:
        if new > previous:
            raise ValueError(f"{event.event_type.value} no puede incrementar saldo")
        return

    if event.event_type == BottleLedgerEventType.AJUSTE:
        if not str(event.reason or "").strip():
            raise ValueError("AJUSTE requiere reason auditable")
        return

    # TRANSFERENCIA, SALIDA_SERVICIO y RETORNO pueden mantener o reducir saldo según evidencia operativa.
    if new > previous and event.event_type != BottleLedgerEventType.RETORNO:
        raise ValueError(f"{event.event_type.value} no puede incrementar saldo")
